import React, { useState, useEffect, useCallback } from 'react'
import { motion } from 'framer-motion'
import {
  AlertTriangle,
  Calendar,
  Clock,
  Filter,
  ChevronDown,
  ChevronUp,
  ChevronLeft,
  ChevronRight,
  Search,
  MapPin,
  Users,
  FileText,
  Eye,
  RefreshCw
} from 'lucide-react'
import { Button } from './ui/button'
import { Card, CardContent, CardHeader, CardTitle } from './ui/card'
import { Input } from './ui/input'
import { Select } from './ui/select'
import { useApi } from '../hooks/useApi'
import { api } from '../lib/api'
import type { ConflictResponse } from '../types/conflicts'
import { getConflictSeverityInfo, formatConflictType } from '../types/conflicts'

interface ConflictReportFilters {
  start_date_after?: string
  end_date_before?: string
  venue_id?: string
  team_id?: number
  limit: number
  offset: number
}

interface ConflictReportResponse {
  conflicts: ConflictResponse[]
  total: number
  limit: number
  offset: number
  has_next: boolean
  has_prev: boolean
}

interface SortConfig {
  key: keyof ConflictResponse | null
  direction: 'asc' | 'desc'
}

const ConflictReportView: React.FC = () => {
