  const [filters, setFilters] = useState<ConflictReportFilters>({
    limit: 10,
    offset: 0
  })

  // State for sorting
  const [sortConfig, setSortConfig] = useState<SortConfig>({
    key: null,
    direction: 'asc'
  })

