    try {
      await fetchConflicts(`/api/scheduling/conflicts?${new URLSearchParams(
        Object.entries(filters).reduce((acc, [key, value]) => {
          if (value !== undefined && value !== null && value !== '') {
            acc[key] = String(value)
          }
          return acc
        }, {} as Record<string, string>)
      ).toString()}`)
    } catch (error) {
